#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	
	while(t--){
	    int n;
	    cin>>n;
	    
	    vector<long long>a(3*n);
	    for(auto &x : a) cin>>x;
	    
	    sort(a.rbegin(),a.rend());
	    
	    vector<long long> pref(3*n+1,0);
	    
	    for(int i=0;i<3*n;i++)
	        pref[i+1]=pref[i]+a[i];
	        
	        auto value=[&](int x,int y)->long long{
	            int j=x+2*y;
	            int k=3*n-2*x-y;
	            return 2LL*pref[x]+pref[j]+3LL*pref[k];
	        };
	        long long ans=0;
	        
	        for(int x=0;x<=n;x++){
	            int maxY=n-x;
	            int lo=0,hi=maxY;
	            
	            while(lo<hi){
	                int mid=(lo+hi)/2;
	                int j=x+2*mid;
	                int k=3*n-2*x-mid;
	                
	                long long delta=a[j]+a[j+1]-3LL*a[k-1];
	                if(delta>=0)
	                  lo=mid+1;
	                  else
	                  hi=mid;
	            }
	            ans=max(ans,value(x,lo));
	            
	            if(lo>0)
	            ans=max(ans,value(x,lo-1));
	        }
	        cout<<ans<<'\n';
	    }
	    

}
